<?php include '../auth/cek_login.php';include '../koneksi.php';$p=mysqli_query($conn,'SELECT * FROM pelanggan ORDER BY nama');$m=mysqli_query($conn,"SELECT * FROM mobil WHERE status='Tersedia'");if(isset($_POST['simpan'])){$pid=(int)$_POST['pelanggan'];$mid=(int)$_POST['mobil'];$a=new DateTime($_POST['tanggal_sewa']);$b=new DateTime($_POST['tanggal_kembali']);$hari=max(1,$a->diff($b)->days);$s=mysqli_prepare($conn,'SELECT harga_sewa FROM mobil WHERE id=? AND status="Tersedia"');mysqli_stmt_bind_param($s,'i',$mid);mysqli_stmt_execute($s);$x=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if($x&&$b>=$a){$harga=$x['harga_sewa'];$total=$harga*$hari;$kode='TRX'.date('YmdHis');$s=mysqli_prepare($conn,'INSERT INTO transaksi(kode_transaksi,id_pelanggan,id_mobil,tanggal_sewa,tanggal_rencana_kembali,harga_per_hari,lama_sewa,total_harga) VALUES(?,?,?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'siissiii',$kode,$pid,$mid,$_POST['tanggal_sewa'],$_POST['tanggal_kembali'],$harga,$hari,$total);mysqli_stmt_execute($s);mysqli_query($conn,"UPDATE mobil SET status='Disewa' WHERE id=$mid");header('Location: index.php');exit;}}?><!doctype html><html><head><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content form-page"><h1>Transaksi Baru</h1><form method="post"><label>Pelanggan</label><select name="pelanggan" required><option value="">Pilih</option><?php while($x=mysqli_fetch_assoc($p)):?><option value="<?=$x['id']?>"><?=$x['nama']?></option><?php endwhile;?></select><label>Mobil</label><select name="mobil" required><option value="">Pilih</option><?php while($x=mysqli_fetch_assoc($m)):?><option value="<?=$x['id']?>"><?=$x['merk']?> <?=$x['tipe']?> - <?=$x['nomor_polisi']?></option><?php endwhile;?></select><label>Tanggal Sewa</label><input type="date" name="tanggal_sewa" value="<?=date('Y-m-d')?>" required><label>Tanggal Kembali</label><input type="date" name="tanggal_kembali" required><button name="simpan">Simpan</button></form></div></body></html>
